import pytest


def fact(n: int) -> int:
    """Return n! (the factorial of n) for n >= 0.

    fact(0) == 1. Raises ValueError when n is negative.
    """
    if n < 0:
        raise ValueError(f"fact() is undefined for negative n: {n}")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result


def test_fact_zero() -> None:
    assert fact(0) == 1


def test_fact_one() -> None:
    assert fact(1) == 1


def test_fact_small() -> None:
    assert fact(5) == 120


def test_fact_ten() -> None:
    assert fact(10) == 3_628_800


def test_fact_twenty() -> None:
    assert fact(20) == 2_432_902_008_176_640_000


def test_fact_negative_raises() -> None:
    with pytest.raises(ValueError):
        fact(-1)
